#include <limits.h>
#include <stdio.h>

int will_wrap(int x) {
    return x + 1 > x;        /* compiler may fold this to: return 1; */
}

int main(void) {
    printf("%d\n", will_wrap(INT_MAX));   /* -O0 prints 0, -O2 prints 1 */
    return 0;
}

#include <limits.h>
#include <stdbool.h>

bool safe_add(int a, int b, int *out) {
    if ((b > 0 && a > INT_MAX - b) || (b < 0 && a < INT_MIN - b))
        return false;
    *out = a + b;
    return true;
}
/* or: if (__builtin_add_overflow(a, b, out)) return false; */

int arr[5] = {1, 2, 3, 4, 5};
for (int i = 0; i <= 5; i++)       /* off-by-one: i == 5 is out of bounds */
    printf("%d ", arr[i]);

bool flag;                         /* uninitialized automatic variable */
if (flag) puts("TRUE");            /* UB: may print either, or neither */

int p = 4;
int r = ++p * p++;     /* UB: p modified twice, unsequenced */

int i = 1;
int a[3] = {0};
a[i] = i++;            /* UB: which i for the index? */

int j = 1;
j++;                   /* fine: split into separate statements */
a[j] = j;

float f = 1.0f;
unsigned u1 = *(unsigned *)&f;       /* UB: strict aliasing violation */

unsigned u2;
memcpy(&u2, &f, sizeof u2);          /* defined; compiles to one movd */

union { float f; unsigned u; } pun = { .f = 1.0f };
unsigned u3 = pun.u;                 /* defined in C, not in C++ */

void bad(int *p) {
    int v = *p;              /* dereference first... */
    if (p == NULL) return;   /* ...so this test can be removed */
    use(v);
}
void good(int *p) {
    if (p == NULL) return;   /* check first */
    use(*p);
}
